INSERT INTO `footer_settings` (`id`, `brand_initials`, `brand_name`, `brand_title`, `brand_bio`, `availability_status`, `nav_links`, `technologies`, `email`, `phone`, `location`, `contact_note`, `copyright_text`, `visible_sections`, `updated_at`) VALUES
(1, 'FN', 'Farshad Nabizadeh', 'Full-Stack Software Engineer', 'Dedicated to architecting high-performance web applications, scalable APIs, reactive frontends, and comprehensive computer science knowledge bases.', '', '[{\"url\": \"index.php\", \"label\": \"Questions Base\"}, {\"url\": \"projects.php\", \"label\": \"Projects Portfolio\"}, {\"url\": \"freelance.php\", \"label\": \"Freelance Hub\"}, {\"url\": \"profile.php\", \"label\": \"Resume & CV\"}, {\"url\": \"profile.php#skills\", \"label\": \"Technical Skills\"}, {\"url\": \"profile.php#experience\", \"label\": \"Career Timeline\"}]', '[\"React\", \"Next.js (SSR)\", \"TypeScript\", \"PHP & Laravel\", \"Node.js\", \"Tailwind CSS\", \"Redux Toolkit\", \"MySQL & Redis\", \"Docker & Nginx\", \"RESTful APIs\", \"Clean Code\"]', 'farshad.nabizade@gmail.com', '+98 912 345 6789', 'Tehran, Iran', 'Feel free to reach out for collaborations, technical inquiries, or consulting.', 'All rights reserved. • Engineered with modern web standards.', '{\"nav\": true, \"tech\": true, \"brand\": true, \"contact\": true}', '2026-09-07 10:26:24');
INSERT INTO `profile` (`id`, `full_name`, `headline`, `avatar_url`, `email`, `phone`, `location_province`, `location_city`, `address`, `github`, `linkedin`, `age`, `gender`, `marital_status`, `military_status`, `work_experience_years`, `salary_expectation`, `education_degree`, `education_school`, `education_years`, `education_gpa`, `about_me`, `skills`, `experiences`, `courses`, `languages`, `software`, `updated_at`) VALUES
(1, 'Farshad Nabizade', 'Full-Stack Web Developer', NULL, 'geoexplorerx2@gmail.com', '09218124475', 'Tehran', 'Tehran', 'Piroozi, Tehran, Iran', 'https://github.com/farshad-nabizade', 'https://linkedin.com', 34, 'Male', 'Single', 'Exempted', 7, '45 - 60 Million Tomans', 'Bachelor: Computer Engineering', 'IAU', '2016 - 2019', '16.4', 'Full-stack developer with over 6 years of hands-on experience in designing and building scalable, secure, and maintainable systems. Proficient in frontend technologies including React, Next.js, Redux Toolkit, TypeScript, and Tailwind CSS, and experienced in backend development with PHP/Laravel, Node.js, Express, MySQL, PostgreSQL, Redis, and RESTful architectures. Skilled in implementing MVC architecture and applying object-oriented design principles such as SOLID to produce clean, extensible, and standards-compliant code. Familiar with SSR architectures, component-based design, advanced caching strategies, and modular system development. Strong DevOps background with practical experience in Docker, Nginx, Reverse Proxy, SSL, DNS, CI/CD pipelines, Linux server administration, service configuration, and performance optimization. Focused on delivering fast, reliable, user-centric, and well-documented products using modern architectures and a Clean Code approach.', '{\"Frontend & UI\": [\"React\", \"Next.js (SSR / CSR)\", \"TypeScript\", \"JavaScript\", \"Tailwind CSS\", \"Redux Toolkit\", \"Single Page Applications (SPA)\", \"Component-Driven Architecture\"], \"Backend & APIs\": [\"PHP\", \"Laravel\", \"Laravel Eloquent ORM\", \"Laravel Eloquent Relationships\", \"Laravel Race Conditions\", \"Node.js\", \"Express.js\", \"RESTful APIs\", \"MVC Architecture\"], \"Databases & Caching\": [\"MySQL\", \"PostgreSQL\", \"Redis\", \"Database Design Principles\"], \"Architecture & Quality\": [\"SOLID Principles\", \"Object Oriented Programming (OOP)\", \"Test-Driven Development (TDD)\", \"Reactive Architecture\", \"Clean Code\"], \"DevOps & Infrastructure\": [\"Docker\", \"Nginx\", \"Reverse Proxy\", \"SSL / TLS\", \"DNS Management\", \"CDN Rules & Firewall Policies\", \"CI/CD Pipelines\", \"Linux Server Administration (Ubuntu)\", \"VPS Security Hardening\", \"Mail Server (SMTP)\"]}', '[{\"role\": \"JavaScript Front-End Developer (TypeScript, React, Next.js)\", \"period\": \"June 2025 until now (1 year and 2 months)\", \"company\": \"Gareno Pargas\", \"location\": \"Iran, Tehran\", \"responsibilities\": [\"Improved the UI and responsiveness of an enterprise ERP system by redesigning multiple frontend modules using a modular and component-based architecture.\", \"Refactored existing Spring Boot client-side interfaces to resolve performance issues and deliver a smoother user experience.\", \"Developed a TypeScript-based website using a fully component-driven structure.\", \"Implemented a dealership information module using Next.js with SSR to enhance SEO and reduce time-to-first-byte.\", \"Built an internal Wallet module using Next.js, TypeScript, Tailwind CSS, and Redux Toolkit, enabling real-time endpoint communication and improving internal financial workflows.\", \"Designed and developed an end-to-end marketplace website (BazarGah GhateSto) using Next.js, TypeScript, Tailwind CSS, and Redux Toolkit with emphasis on scalability, modern UI/UX, and high performance.\", \"Ensured frontend optimization by applying reactive architecture principles and real-time asynchronous data handling.\"]}, {\"role\": \"Full-Stack Software Engineer (Next.js, React, Laravel)\", \"period\": \"July 2024 until September 2025 (1 year and 2 months)\", \"company\": \"Safiran-e-Yegane\", \"location\": \"Iran, Tehran\", \"responsibilities\": [\"Designed and developed high-performance Single Page Applications (SPA) using React, Next.js, Tailwind CSS, and Redux Toolkit.\", \"Built user and admin dashboards with smart, responsive, and user-friendly interfaces.\", \"Developed optimized RESTful APIs with efficient endpoints to improve data handling and reduce response time.\", \"Implemented Server-Client Component architecture in Next.js to achieve maximum performance and faster load times.\", \"Integrated MySQL and Redis for robust data management, effective caching, and overall system performance improvement.\", \"Configured and managed Cross-Origin policies to ensure secure resource sharing across services.\", \"Performed updates, security patching, system monitoring, and advanced performance optimization.\", \"Deployed and maintained SSL certificates to enable secure and encrypted communications.\", \"Configured and managed DNS settings for stable and reliable domain routing.\", \"Implemented CDN rules, firewall policies, and Nginx proxy_pass for secure and optimized traffic management.\", \"Set up and configured mail server services to support organizational communication needs.\", \"Enhanced network security through Reverse Proxy configuration, access control policies, and server hardening.\"]}, {\"role\": \"Senior Full-Stack Developer\", \"period\": \"May 2022 until August 2024 (2 years and 3 months)\", \"company\": \"Hotelistan Global Travel Services\", \"location\": \"Turkey\", \"responsibilities\": [\"Improved API connectivity to enable faster and more reliable data exchange.\", \"Implemented automated database backups to enhance data security and prevent data loss.\", \"Designed a user-friendly location search interface to improve usability and user experience.\", \"Developed responsive Single Page Applications (SPA) using React, Next.js, and Tailwind CSS.\", \"Designed and implemented a custom CRM system using Laravel for comprehensive customer management.\", \"Built an admin panel for managing server operations and monitoring system data.\"]}, {\"role\": \"Freelance Full-Stack Developer\", \"period\": \"April 2021 until January 2022 (9 months)\", \"company\": \"Freelance\", \"location\": \"Turkey\", \"responsibilities\": [\"Optimized website performance and loading speed through advanced caching, code refactoring, and server-side improvements.\", \"Built fully responsive UI layouts to ensure seamless user experience across mobile and desktop devices.\", \"Installed and configured VPS servers, including security hardening, firewall rules, SSH access, and service optimization.\", \"Implemented secure VPN environments for private networking, encrypted communication, and improved data protection.\", \"Debugged and resolved critical frontend and backend issues across multiple client websites.\", \"Set up and configured mail servers (mail-server, SMTP) for reliable email delivery, domain authentication, and organizational communication.\"]}, {\"role\": \"Full-Stack Web Developer (PHP, MySQL, Ubuntu Server)\", \"period\": \"March 2020 until May 2021 (1 year and 2 months)\", \"company\": \"Tema Istanbul\", \"location\": \"Turkey\", \"responsibilities\": [\"Developed a web-based panel using PHP/MySQL with real-time calculations based on complex business formulas.\", \"Automated Excel data extraction, cleaning, and processing to eliminate human errors and improve calculation accuracy.\", \"Implemented authentication and role-based access control to protect sensitive business data.\", \"Installed and configured an Ubuntu server and enabled secure online access without relying on cloud hosting.\", \"Designed a simple and intuitive user interface optimized for non-technical users, requiring minimal training.\"]}, {\"role\": \"Full-Stack Developer (Laravel, MySQL, jQuery)\", \"period\": \"June 2018 until January 2019 (7 months)\", \"company\": \"Vira Negar\", \"location\": \"Iran, Tehran\", \"responsibilities\": [\"Implemented a secure login system using Laravel to enhance security and enforce user access control.\", \"Designed and developed a dynamic admin panel using Laravel Blade, CSS/SASS, and jQuery to improve user experience.\", \"Created custom widgets to simplify data presentation and streamline user interactions.\", \"Built responsive, mobile-first user interfaces optimized for all device types.\", \"Optimized MySQL queries to improve data processing speed and overall server performance.\"]}]', '[{\"year\": \"2018\", \"title\": \"CCNP\", \"duration\": \"3 Months\", \"institute\": \"TIT\"}, {\"year\": \"2017\", \"title\": \"CCNA\", \"duration\": \"3 Months\", \"institute\": \"TIT\"}, {\"year\": \"2016\", \"title\": \"Network +\", \"duration\": \"1 Month\", \"institute\": \"TIT\"}]', '[{\"language\": \"English\", \"proficiency\": \"Intermediate\"}, {\"language\": \"Persian\", \"proficiency\": \"Native\"}]', '[{\"name\": \"Microsoft Word\", \"proficiency\": \"Intermediate\"}, {\"name\": \"Microsoft Excel\", \"proficiency\": \"Intermediate\"}, {\"name\": \"Microsoft Powerpoint\", \"proficiency\": \"Intermediate\"}]', '2026-08-19 13:07:50');
INSERT INTO `projects` (`id`, `title`, `description`, `project_url`, `github_url`, `company`, `duration`, `role`, `technologies`, `highlights`, `featured`, `created_at`, `updated_at`) VALUES
(1, 'BazarGah GhateSto (Automotive Marketplace & E-Commerce)', 'A scalable, modern automotive marketplace and e-commerce platform built to streamline spare parts procurement, merchant listings, and customer orders with high-performance real-time search and responsive UI.', 'https://example.com/bazargah', 'https://github.com/farshad-nabizade/bazargah-marketplace', 'Gareno Pargas', 'June 2025 - Present (1 yr 2 mos)', 'Front-End Lead Developer', '[\"Next.js\", \"TypeScript\", \"Tailwind CSS\", \"Redux Toolkit\", \"REST APIs\", \"SPA\"]', '[\"Designed and developed end-to-end marketplace frontend from scratch using Next.js and Tailwind CSS.\", \"Implemented centralized state management with Redux Toolkit for shopping carts and user flows.\", \"Optimized page load speed and Lighthouse metrics through modular component architecture.\"]', 1, '2026-08-19 13:12:46', '2026-08-19 13:12:46'),
(2, 'Enterprise ERP Modular System Overhaul2', 'Comprehensive redesign and frontend modernization of an enterprise ERP system, replacing legacy client-side interfaces with modern Next.js modules communicating with Spring Boot microservices.', 'https://example.com/erp-system', '', 'Gareno Pargas', 'June 2025 - Present', 'Front-End Architect & Developer', '[\"Next.js (SSR)\", \"React\", \"TypeScript\", \"Spring Boot APIs\", \"Reactive Architecture\"]', '[\"Refactored legacy Spring Boot client interfaces to resolve UI rendering bottlenecks.\", \"Adopted reactive architecture principles for real-time asynchronous data feeds.\", \"Improved overall user satisfaction and workflow efficiency across operational departments.\"]', 1, '2026-08-19 13:12:46', '2026-08-19 13:19:14'),
(3, 'Internal Financial Wallet & Transaction Subsystem', 'Dedicated internal wallet module built for high-security financial transactions, ledger balancing, and real-time status notifications for corporate operations.', '', 'https://github.com/farshad-nabizade/wallet-module', 'Gareno Pargas', '2025', 'Full-Stack Developer', '[\"Next.js\", \"TypeScript\", \"Tailwind CSS\", \"Redux Toolkit\", \"RESTful Endpoints\"]', '[\"Engineered real-time transaction updates and ledger synchronization.\", \"Integrated strict client-side validation and secure API authentication tokens.\", \"Streamlined internal corporate billing and payment reconciliation workflows.\"]', 0, '2026-08-19 13:12:46', '2026-08-19 13:12:46'),
(4, 'Dealership Information & Auto Services SSR Platform', 'High-throughput public-facing dealership directory and automotive services search engine optimized for search indexing and zero latency.', 'https://example.com/dealerships', '', 'Gareno Pargas', '2025', 'Next.js Specialist', '[\"Next.js SSR\", \"SEO Optimization\", \"TypeScript\", \"Tailwind CSS\"]', '[\"Implemented Server-Side Rendering (SSR) to achieve top Google search rankings.\", \"Reduced Time-to-First-Byte (TTFB) significantly with edge caching strategies.\", \"Created dynamic geolocation-based dealership locator with interactive maps.\"]', 0, '2026-08-19 13:12:46', '2026-08-19 13:12:46'),
(5, 'Safiran Smart Analytics Dashboard & Admin Control Portal', 'Unified administrative portal and analytics dashboard with interactive charts, user permissions, and real-time operational telemetry.', 'https://example.com/safiran-portal', 'https://github.com/farshad-nabizade/smart-dashboard', 'Safiran-e-Yegane', 'July 2024 - Sept 2025 (1 yr 2 mos)', 'Full-Stack Software Engineer', '[\"React\", \"Next.js\", \"Laravel\", \"MySQL\", \"Redis\", \"Nginx\", \"Docker\"]', '[\"Engineered high-performance Single Page Applications with Server/Client components.\", \"Built optimized Laravel RESTful APIs with Redis caching layer.\", \"Configured Nginx reverse proxy, SSL TLS termination, and firewall policies.\"]', 1, '2026-08-19 13:12:46', '2026-08-19 13:12:46'),
(6, 'Hotelistan Global Travel & Core Booking Services', 'High-availability reservation engine and B2B API distribution layer connecting international hotel suppliers with booking engines.', 'https://example.com/hotelistan', '', 'Hotelistan Global Travel Services (Turkey)', 'May 2022 - Aug 2024 (2 yrs 3 mos)', 'Senior Full-Stack Developer', '[\"PHP\", \"MySQL\", \"Redis\", \"REST APIs\", \"Automated Backups\", \"Linux Ubuntu\"]', '[\"Improved B2B API connectivity for seamless multi-supplier data exchange.\", \"Implemented automated database disaster recovery routines and replication backups.\", \"Enhanced backend stability to support high concurrency during peak travel seasons.\"]', 1, '2026-08-19 13:12:46', '2026-08-19 13:12:46');
INSERT INTO `questions` (`id`, `question`, `answer`, `category`) VALUES
(1, 'How do you initialize a Node.js project, install Express, and configure a basic HTTP server listening on a custom port with graceful shutdown handlers?', '```js\nnpx react-app\n```', 'Express.js & Prisma with MySQL'),
(2, 'How do you handle environment variables using dotenv to configure ports, database URLs, and server environments (development/production) safely in Express?', '', 'Express.js & Prisma with MySQL'),
(3, 'How do you define basic HTTP route handlers for GET, POST, PUT, PATCH, and DELETE, and access query parameters (req.query), path parameters (req.params), and headers (req.headers)?', '', 'Express.js & Prisma with MySQL'),
(4, 'How do you configure built-in body parsers (express.json() and express.urlencoded()) to process incoming JSON and URL-encoded request payloads?', '', 'Express.js & Prisma with MySQL'),
(5, 'How do you use express.Router() to structure routes modularly into separate resource files (e.g., /api/v1/users, /api/v1/posts, /api/v1/comments)?', '', 'Express.js & Prisma with MySQL'),
(6, 'How do you use route parameter middleware (router.param()) to automatically validate or pre-fetch resources based on an ID parameter across routes?', '', 'Express.js & Prisma with MySQL'),
(7, 'How does the middleware pipeline work in Express, and how do you write a custom application-level logger middleware that calculates request execution time using next()?', '', 'Express.js & Prisma with MySQL'),
(8, 'How do you write and apply route-specific and router-level middleware to modify the req object (e.g., attaching request IDs or timestamp metadata)?', '', 'Express.js & Prisma with MySQL'),
(9, 'How do you implement a centralized global error-handling middleware with 4 parameters (err, req, res, next) to capture sync and async errors and send uniform JSON error responses?', '', 'Express.js & Prisma with MySQL'),
(10, 'How do you handle asynchronous errors in Express routes using express-async-errors or a custom asyncHandler wrapper function without repetitive try-catch blocks?', '', 'Express.js & Prisma with MySQL'),
(11, 'How do you create custom application error classes extending Error (e.g., NotFoundError, BadRequestError, UnauthorizedError) with dedicated HTTP status codes?', '', 'Express.js & Prisma with MySQL'),
(12, 'How do you catch unhandled 404 routes for undefined endpoints in Express using catch-all fallback middleware?', '', 'Express.js & Prisma with MySQL'),
(13, 'How do you install Prisma CLI and Client, initialize Prisma (prisma init), and configure connection strings for MySQL in .env?', '', 'Express.js & Prisma with MySQL'),
(14, 'How do you configure the datasource and generator blocks in schema.prisma for MySQL with specific preview features?', '', 'Express.js & Prisma with MySQL'),
(15, 'How do you implement a Singleton pattern for PrismaClient to prevent opening duplicate database connection pools during development hot-reloading?', '', 'Express.js & Prisma with MySQL'),
(16, 'How do you define primary keys in Prisma using auto-incrementing integers (@id @default(autoincrement())), UUIDs (@default(uuid())), and CUIDs (@default(cuid()))?', '', 'Express.js & Prisma with MySQL'),
(17, 'How do you map Prisma fields to native MySQL data types (e.g., @db.VarChar(255), @db.Text, @db.Decimal(10, 2), @db.TinyInt, @db.DateTime)?', '', 'Express.js & Prisma with MySQL'),
(18, 'How do you define default values (@default(now()), @default(false)), optional fields (?), and mapped table/column names (@@map, @map) in Prisma?', '', 'Express.js & Prisma with MySQL'),
